import type { HeightField } from '../physics/HeightField';
import type { TerrainSampler } from './terrain';

/** Track data (§8.1). Tracks are data; geometry is generated by trackBuilder. */
export type ThemeKind = 'forest' | 'seaside' | 'canyon';

export interface TrackTheme {
  kind: ThemeKind;
  ground: string;
  road: string;
  curbA: string;
  curbB: string;
  bumperA: string;
  bumperB: string;
  /** Terrain palette: two grass/ground tones, steep rock, low sand, water. */
  groundB: string;
  rock: string;
  sand: string;
  water: string;
  /** Sky gradient + fog. */
  skyTop: string;
  skyHorizon: string;
}

/** Ground around the road (2.5D). Heights in meters. */
export interface TerrainSpec {
  /** Base ground height away from the road. */
  baseHeight: number;
  /** Noise hill amplitude and scale (m). */
  hillAmplitude: number;
  hillScale: number;
  /** Distance (beyond the walls) over which ground blends from road height to base: small = cliffs. */
  blendWidth: number;
  /** Tall mesas/hills far from the road. */
  peaks?: { amplitude: number; scale: number; minDistance: number };
  /** Sea: everything on the far side of this line drops to `seaLevel` (cliffs!). */
  coast?: { nx: number; nz: number; d: number; seaLevel: number };
  /** River polyline carved into the ground with water at `level`. */
  river?: { points: [number, number][]; width: number; level: number };
}

export type LandmarkKind = 'lighthouse' | 'windmill' | 'mesa' | 'boat' | 'bigTree' | 'archRock';

export interface Landmark {
  kind: LandmarkKind;
  x: number;
  z: number;
  rotation?: number;
  scale?: number;
}

export interface TrackFeatures {
  /** Road height keypoints along the lap: [fraction from start line 0..1, height m]. */
  elevation?: [number, number][];
  /** Kicker ramps on the road: lip at `at` (fraction), rising over `length` m. */
  ramps?: { at: number; length: number; height: number }[];
  /** Short steep dips (jumpable gaps): centered at `at`, `length` m long, `depth` m deep. */
  dips?: { at: number; length: number; depth: number }[];
  /** Boost pads (fractions along the lap). */
  boostPads?: number[];
}

export interface TrackDefinition {
  id: string;
  name: string;
  laps: number;
  /** XZ points of a closed centerline loop, in race direction. */
  controlPoints: [number, number][];
  roadWidth: number;
  checkpointCount: number;
  /** Control point where the start/finish line sits. */
  startIndex: number;
  theme: TrackTheme;
  decorationSeed: number;
  terrain: TerrainSpec;
  features?: TrackFeatures;
  landmarks?: Landmark[];
}

export interface Checkpoint {
  index: number;
  sample: number;
  x: number;
  z: number;
  /** Unit tangent (race direction). */
  tx: number;
  tz: number;
  halfWidth: number;
}

export interface GridSlot {
  x: number;
  z: number;
  heading: number;
}

export type DecorationKind =
  'tree' | 'pine' | 'bush' | 'rock' | 'flower' | 'block' | 'cactus' | 'mushroom' | 'palm' | 'tuft';

export interface Decoration {
  kind: DecorationKind;
  x: number;
  z: number;
  scale: number;
  rotation: number;
  /** Palette index for kinds with color variants (blocks, flowers). */
  variant: number;
}

/** Flat darker-grass patch on the ground. */
export interface GroundPatch {
  x: number;
  z: number;
  sx: number;
  sz: number;
  rotation: number;
}

/** Big soft grassy hill, well away from the road. */
export interface Mound {
  x: number;
  z: number;
  radius: number;
  height: number;
}

/** Object placed along the track edge (tire stacks, flag posts). */
export interface EdgeProp {
  x: number;
  z: number;
  rotation: number;
  variant: number;
}

export interface Grandstand {
  x: number;
  z: number;
  /** Yaw so the stand's front faces the track. */
  rotation: number;
  length: number;
}

export interface TrackScenery {
  patches: GroundPatch[];
  mounds: Mound[];
  tireStacks: EdgeProp[];
  flags: EdgeProp[];
  grandstand: Grandstand;
}

export interface RibbonGeometry {
  positions: Float32Array;
  normals: Float32Array;
  indices: Uint32Array;
  colors?: Float32Array;
}

/** A wall block between two consecutive wall polyline points. */
export interface WallBlock {
  x: number;
  z: number;
  /** Road height under the block (2.5D). */
  y: number;
  length: number;
  rotation: number;
  /** 0/1 alternating color index. */
  color: 0 | 1;
}

/** A road-aligned rectangle (ramp lip area, boost pad). */
export interface RoadPatch {
  sample: number;
  x: number;
  z: number;
  y: number;
  heading: number;
  length: number;
  width: number;
}

export interface TrackData {
  def: TrackDefinition;
  /** Road height per centerline sample (2.5D). */
  h: Float32Array;
  ramps: RoadPatch[];
  boostPads: RoadPatch[];
  /** Road height lookup for physics. */
  heightField: HeightField;
  /** Ground around the road (terrain mesh, water, prop placement). */
  terrain: TerrainSampler;
  length: number;
  sampleCount: number;
  /** Centerline samples (index 0 = start/finish line). */
  px: Float32Array;
  pz: Float32Array;
  tx: Float32Array;
  tz: Float32Array;
  /** Cumulative arc length at each sample. */
  dist: Float32Array;
  road: RibbonGeometry;
  curbs: RibbonGeometry;
  /** Wall segments [ax, az, bx, bz]… for CollisionWorld. */
  wallSegments: Float32Array;
  wallBlocks: WallBlock[];
  /** Offset from centerline to the wall collision line. */
  wallOffset: number;
  checkpoints: Checkpoint[];
  startGrid: GridSlot[];
  decorations: Decoration[];
  scenery: TrackScenery;
  bounds: { minX: number; maxX: number; minZ: number; maxZ: number };
}
